INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-001', 'sm.rbv', 1401, 'کدام گزینه، ویژگی‌های منبع استراتژیک در مدل بارنی را به‌طور کامل توصیف می‌کند؟', '["ارزش‌مند، کمیاب، تقلیدناپذیر و جایگزینی‌ناپذیر","فراوان، ارزان و در دسترس","قابل کپی، ملموس و قابل معامله","شهودی، ملموس و ماندگار"]'::jsonb, 0, 'مدل VRIN بارنی: منبع باید ارزش‌آفرین، کمیاب، تقلیدناپذیر و بدون جایگزین باشد تا مزیت پایدار بسازد.', 'دام رایج طراح: جایگزینی «جایگزینی‌ناپذیر» با «قابل معامله» یا خلط VRIN با VRIO.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-002', 'sm.rbv', 1403, 'قابلیت‌های پویا (تیس) عمدتاً برای برطرف‌کردن کدام محدودیتِ دیدگاه مبتنی بر منابع مطرح شدند؟', '["سکون قابلیت‌ها در محیط‌های به‌سرعت متغیر","تأکید بیش از حد بر مشتری","نادیده‌گرفتن هزینهٔ تولید","تمرکز بر بازارهای محلی"]'::jsonb, 0, 'قابلیت‌های پویا یعنی توان بازآرایی و بازشکل‌دهی شایستگی‌ها برای پاسخ به تغییرات محیطی.', 'دام: گزینه‌هایی که «بازآرایی منابع در محیط متغیر» را با «کاهش هزینه» اشتباه می‌گیرند.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-003', 'sm.value_chain', 1400, 'در زنجیرهٔ ارزش پورتر، فعالیت‌های «حاشیه‌ساز» کدام‌اند؟', '["زیرساخت سازمان، مدیریت منابع انسانی، توسعهٔ فناوری و خرید","ورودی‌ها، عملیات، خروجی‌ها، بازاریابی و فروش و خدمات","فقط بازاریابی و فروش","فقط عملیات و خدمات"]'::jsonb, 0, 'فعالیت‌های اصلی مستقیماً محصول/خدمت را می‌سازند؛ حاشیه‌سازها از همهٔ فعالیت‌ها پشتیبانی می‌کنند.', 'دام کلاسیک: جابه‌جایی فهرست فعالیت‌های اصلی و حاشیه‌ساز.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-004', 'sm.portfolio', 1402, 'در ماتریس BCG، واحدی که سهم بازار کم اما رشد بازار بالا دارد چه نامیده می‌شود؟', '["علامت سؤال","ستاره","گاو شیری","سگ"]'::jsonb, 0, 'Question Mark: رشد بالا، سهم کم؛ تصمیم سرمایه‌گذاری یا کنارگذاری.', 'دام: خلط «ستاره» با «علامت سؤال» به‌دلیل رشد بالای مشترک.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-005', 'stats.scales', 1399, '«رتبه‌بندی رضایت کارکنان به‌صورت ضعیف/متوسط/خوب» از چه مقیاسی است؟', '["رتبه‌ای (ترتیبی)","اسمی","نسبتی","فاصله‌ای"]'::jsonb, 0, 'ترتیب معنادار اما فاصلهٔ برابر تضمین‌نشده = مقیاس ترتیبی.', 'دام: خلط ترتیبی با فاصله‌ای؛ در فاصله‌ای فواصل برابر معنی دارند.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-006', 'stats.anova', 1401, 'کدام مفروض برای اجرای ANOVA پارامتریک ضروری است؟', '["همسانی واریانس گروه‌ها و نرمال‌بودن توزیع خطا","همبستگی بالای متغیرها","داده‌های رتبه‌ای بدون توزیع خاص","نمونه‌گیری خوشه‌ای"]'::jsonb, 0, 'ANOVA پارامتریک: نرمال بودن، همسانی واریانس (Levene) و استقلال مشاهدات.', 'دام: گزینه‌های مربوط به آزمون‌های ناپارامتریک (مانند Kruskal-Wallis) به‌عنوان مفروض پارامتریک.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-007', 'mb.structure', 1400, 'برنز و استاکر، سازمان‌های با محیط پایدار و فناوری تولید انبوه را کدام نوع ساختار می‌دانند؟', '["مکانیکی","ارگانیک","دوپهلو","ماتریسی"]'::jsonb, 0, 'محیط پایدار + تولید انبوه = ساختار مکانیکی (رسمی، متمرکز، سلسله‌مراتبی).', 'دام: خلط شرایط محیطی مناسب ارگانیک (محیط متغیر) با مکانیکی.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-008', 'mb.contingency', 1402, 'پژوهش وودوارد نشان داد ارتباط «ساختار و اثربخشی» بستگی دارد به چه عاملی؟', '["فناوری تولید سازمان","اندازهٔ ساختمان","شخصیت مدیر عامل","قیمت سهام"]'::jsonb, 0, 'وودوارد: نوع فناوری تولید (تک‌بشی تا فرایندی) تعیین‌کنندهٔ ساختار اثربخش است.', 'دام: خلط یافتهٔ وودوارد (فناوری) با لارنس و لورش (محیط و عدم‌قطعیت).', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-009', 'mkt.brand', 1401, 'در مدل کاپفرر، کدام عنصر از هرم برند به «روابط مشتری با برند» اشاره دارد؟', '["پرکننده","جنس","شخصیت","منعکس‌کننده"]'::jsonb, 0, 'پرکننده (Relational) لایهٔ بیرونی هرم کاپفرر و مربوط به رابطهٔ مشتری-برند است.', 'دام: ترتیب لایه‌های هرم کاپفرر (فیزیکی، جنس، شخصیت، منعکس‌کننده، پرکننده).', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-010', 'mkt.plc', 1403, 'در مرحلهٔ رشد چرخهٔ عمر محصول، استراتژی پیشنهادی کاتلر برای رهبر بازار چیست؟', '["بهبود کیفیت، افزودن ویژگی و مدل‌های جدید","کاهش شدید قیمت برای حذف رقبا","خروج از بازار","حذف توزیع"]'::jsonb, 0, 'در رشد، تمرکز بر تمایز و گسترش بازار است نه جنگ قیمتی.', 'دام: خلط استراتژی مرحلهٔ رشد با جنگ قیمتی مرحلهٔ بلوغ.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-011', 'mkt.consumer', 1398, 'کدام نظریهٔ انگیزشی، «نیاز به موفقیت (nAch)» را محور توضیح رفتار می‌داند؟', '["مک‌کللند","مزلو","هرزبرگ","وروم"]'::jsonb, 0, 'مک‌کللند: نیاز به موفقیت، قدرت و وابستگی؛ nAch پیش‌بین رفتار کارآفرینانه.', 'دام: خلط nAch مک‌کللند با نیازهای بنیادی مزلو.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-012', 'inno.s_curve', 1402, 'مفهوم «هجوم تکنولوژیک» در منحنی S فاستر چه زمانی رخ می‌دهد؟', '["هنگام گذار به فناوری نسل بعد در نقطهٔ اشباع منحنی فعلی","در آغاز منحنی اول","پس از رقابت قیمتی","قبل از سرمایه‌گذاری اولیه"]'::jsonb, 0, 'Discontinuity: وقتی منحنی فعلی به حد اشباع می‌رسد، مزیت به فناوری جدید سمت راست منحنی می‌رسد.', 'دام: خلط نقطهٔ اشباع منحنی فعلی با شروع منحنی جدید در زمان‌بندی گذار فناوری.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-013', 'inno.ambidextrous', 1401, 'سازمان دوپهلو (O''Reilly و Tushman) به‌طور هم‌زمان چه می‌کند؟', '["بهبود تدریجی کسب‌وکار فعلی + اکتشاف فرصت‌های جدید در واحدهای جداگانه","فقط بهینه‌سازی فرایندهای فعلی","فقط تحقیقات بلندمدت بدون تولید","برون‌سپاری تمام نوآوری‌ها"]'::jsonb, 0, 'Ambidexterity: هم‌زمانی exploitation و exploration از طریق واحدهای ساختاری جدا اما یکپارچهٔ راهبردی.', 'دام: خلط دوپهلو با «فقط تحقیق» یا «فقط بهبود مستمر».', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status, exam_level, content_origin) VALUES ('demo-q-014', 'tech.absorptive', 1403, 'ظرفیت جذب (Absorptive Capacity) بر اساس تعریف کوهن و لوینتال چیست؟', '["توانایی شناسایی، جذب و کاربست دانش بیرونی","میزان سرمایهٔ ثابت شرکت","تعداد پتنت‌های ثبت‌شده","سرعت تولید محصول"]'::jsonb, 0, 'ظرفیت جذب تابع دانش قبلی مرتبط سازمان است و سه مؤلفهٔ شناسایی، جذب و کاربست دارد.', 'دام: تعریف ظرفیت جذب به‌صورت موجودی دارایی به‌جای توانایی فرایندی.', 'demo', 'doctorate', 'synthetic_demo') ON CONFLICT (id) DO UPDATE SET exam_level = EXCLUDED.exam_level, content_origin = EXCLUDED.content_origin;
